1	package ociresources
2	
3	import (
4		"fmt"
5	
6		"github.com/anthnel/devdesk/internal/cache"
7		"github.com/anthnel/devdesk/internal/config"
8		sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
9	)
10	
11	// DEVDESK-510 (NX-07): everything a screen says about a group whose members the
12	// manager refused to list. The wording lives here and nowhere else, as pure
13	// functions of one value, so a change of text is a change of this file.
14	//
15	// None of it carries the manager's error text, a status line from the
16	// management API or the registry URL: the state is a word and an age, and the
17	// way out is repo_prefix.
18	
19	// emptyGroupText is the status line of a group that answered with no member.
20	const emptyGroupText = "No member found — this group is empty"
21	
22	// groupRefusalView is everything the refusal wording may use.
23	type groupRefusalView struct {
24		Refusal  cache.RegistryGroupRefusal // Status, Anonymous, At
25		Known    int                        // members last listed and still cached (0 if never listed)
26		Declared int                        // config entries whose parent is this group (CA5)
27	}
28	
29	// refusedReason is the head of every refusal sentence: it says the members could
30	// not be read, and for whom.
31	func (v groupRefusalView) refusedReason() string {
32		if v.Refusal.Anonymous {
33			return "Members could not be read without credentials"
34		}
35		return "Members could not be read with this account"
36	}
37	
38	// declareAdvice is what the user can do about it.
39	func (v groupRefusalView) declareAdvice() string {
40		if v.Refusal.Anonymous {
41			return "set credentials or declare them by hand with repo_prefix"
42		}
43		return "declare them by hand with repo_prefix"
44	}
45	
46	// refusedFooterText is the footer line after a refused refresh (H1, level Warn).
47	func refusedFooterText(v groupRefusalView) string { return refusedStatusLine(v) }
48	
49	// refusedMembersCell is the Members column of a refused group (H2), plain text
50	// (Rule 122). The state comes first; the count last known stays visible, since a
51	// refusal does not empty the cache (D23); the age is the refusal's.
52	//
53	// Formats: "denied · <age>" when nothing was ever listed, "denied · N known ·
54	// <age>" otherwise, <age> being theme.TimeAgo (Rule 127), at most 11 cells, so at
55	// most 31 for 99 members. State first: the column holds 16 cells at its
56	// narrowest and cuts the end, so "denied" is what stays.
57	func refusedMembersCell(v groupRefusalView) string {
58		if v.Known > 0 {
59			return fmt.Sprintf("denied · %d known · %s", v.Known, timeAgo(v.Refusal.At))
60		}
61		return "denied · " + timeAgo(v.Refusal.At)
62	}
63	
64	// refusedStatusLine is the status line while a refused group row is selected (H3).
65	func refusedStatusLine(v groupRefusalView) string {
66		if v.Declared > 0 {
67			return fmt.Sprintf("%s — %d declared by hand are used", v.refusedReason(), v.Declared)
68		}
69		return v.refusedReason() + " — " + v.declareAdvice()
70	}
71	
72	// refusedDrillInText is the footer warning when → has no member to open (H4).
73	// ctrl+r cannot help after a refusal, so it is not offered.
74	func refusedDrillInText(v groupRefusalView) string {
75		return "No members to open — " + v.declareAdvice()
76	}
77	
78	// groupRefusal returns the refusal that still holds for a group, with the counts
79	// the wording uses. A refusal no more recent than the listing is stale: the
80	// listing was read after it, so it is ignored.
81	func (m *Model) groupRefusal(slug string) (groupRefusalView, bool) {
82		refusal, ok := m.groupRefusals[slug]
83		if !ok {
84			return groupRefusalView{}, false
85		}
86		entry, listed := m.groupCache[slug]
87		if listed && !refusal.At.After(entry.DiscoveredAt) {
88			return groupRefusalView{}, false
89		}
90		return m.refusalView(slug, refusal), true
91	}
92	
93	// refusalView gathers what the wording may use about one group's refusal.
94	func (m *Model) refusalView(slug string, r cache.RegistryGroupRefusal) groupRefusalView {
95		return groupRefusalView{
96			Refusal:  r,
97			Known:    len(m.groupCache[slug].Members),
98			Declared: declaredMembers(m.registries, slug),
99		}
100	}
